pub fn lookup_resolved_sig_with_telemetry(
    env: Rc<ResolvedFuncEnv>,
    name: String,
) -> Option<Rc<ResolvedSigWithOwner>> {
    {
        let scan = env.parents.clone().iter().cloned().fold(
            Rc::new(ParentSigScan {
                sig: std::option::Option::None,
                match_count: 0,
                first_parent: std::option::Option::None,
            }),
            |acc: _, p: Rc<ResolvedFuncEnv>| match v1_rt::map_get(&p.local.clone(), name.clone()) {
                Some(sig) => Rc::new(ParentSigScan {
                    sig: if (acc.sig.clone() != std::option::Option::None) {
                        acc.sig.clone()
                    } else {
                        Some(sig.clone())
                    },
                    match_count: (acc.match_count.clone() + 1),
                    first_parent: if (acc.first_parent.clone() != std::option::Option::None) {
                        acc.first_parent.clone()
                    } else {
                        Some(p.name.clone())
                    },
                }),
                std::option::Option::None => acc.clone(),
            },
        );
        if ((scan.match_count.clone() >= 2) && (scan.sig.clone() != std::option::Option::None)) {
            match scan.first_parent.clone() {
                Some(chosen_parent) => v1_rt::resolution_silent_pick_record_fn_parent_first_hit(
                    env.name.clone(),
                    name.clone(),
                    scan.match_count.clone(),
                    chosen_parent.clone(),
                ),
                std::option::Option::None => {}
            }
        }
        match scan.sig.clone() {
            Some(sig) => match scan.first_parent.clone() {
                Some(owner) => Some(Rc::new(ResolvedSigWithOwner {
                    sig: sig.clone(),
                    owner_module_path: owner.clone(),
                })),
                std::option::Option::None => std::option::Option::None,
            },
            std::option::Option::None => std::option::Option::None,
        }
    }
}

pub fn lookup_resolved_sig(env: Rc<ResolvedFuncEnv>, name: String) -> Rc<FuncSigLookup> {
    match v1_rt::map_get(&env.local.clone(), name.clone()) {
        Some(sig) => Rc::new(FuncSigLookup::FuncSigResolved {
            sig: sig.clone(),
            declared: Rc::new(DeclaredCallableIdentity {
                owner_module_path: env.name.clone(),
                decl_name: name.clone(),
            }),
        }),
        std::option::Option::None => {
            if v1_rt::name_resolution_policy_is_namespace_only() {
                lookup_resolved_sig_unique_across_parents(env.clone(), name.clone())
            } else {
                {
                    let first_hit = if v1_rt::resolution_silent_pick_is_enabled() {
                        lookup_resolved_sig_with_telemetry(env.clone(), name.clone())
                    } else {
                        env.parents.clone().iter().cloned().fold(
                            none_resolved_sig_with_owner(),
                            |acc: _, p: Rc<ResolvedFuncEnv>| match acc.clone() {
                                Some(found) => Some(found.clone()),
                                std::option::Option::None => {
                                    match v1_rt::map_get(&p.local.clone(), name.clone()) {
                                        Some(sig) => Some(Rc::new(ResolvedSigWithOwner {
                                            sig: sig.clone(),
                                            owner_module_path: p.name.clone(),
                                        })),
                                        std::option::Option::None => std::option::Option::None,
                                    }
                                }
                            },
                        )
                    };
                    match first_hit.clone() {
                        Some(found) => Rc::new(FuncSigLookup::FuncSigResolved {
                            sig: found.sig.clone(),
                            declared: Rc::new(DeclaredCallableIdentity {
                                owner_module_path: found.owner_module_path.clone(),
                                decl_name: name.clone(),
                            }),
                        }),
                        std::option::Option::None => Rc::new(FuncSigLookup::FuncSigUnresolved),
                    }
                }
            }
        }
    }
}

pub fn none_resolved_sig_with_owner() -> Option<Rc<ResolvedSigWithOwner>> {
    std::option::Option::None
}

pub fn collect_func_call_edges(
    items: Rc<Vec<Rc<Node>>>,
    local_func_set: Rc<HashMap<String, bool>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<CallEdge>>> {
    Rc::new({
        let mut __result = Vec::new();
        for item in items.iter().cloned() {
            __result.extend(
                (*if (((item.params.clone().len() as i64) > 0)
                    && (item.body.clone() != std::option::Option::None))
                {
                    collect_calls_in_expr(
                        crate::v1_std_core::authored_name_at(source_indices.clone(), item.clone()),
                        item.body.clone().clone().unwrap(),
                        local_func_set.clone(),
                        source_indices.clone(),
                    )
                } else {
                    Rc::new(vec![])
                })
                .iter()
                .cloned(),
            );
        }
        __result
    })
}

pub fn collect_calls_in_expr(
    caller: String,
    texpr: Rc<Node>,
    local_func_set: Rc<HashMap<String, bool>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<CallEdge>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let this_edges = match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f =
                    crate::v1_std_core::expr_call_func_at(texpr.clone(), source_indices.clone());
                if crate::v1_compiler_infer_types::emit_map_has(local_func_set.clone(), f.clone()) {
                    Rc::new(vec![Rc::new(CallEdge {
                        caller: caller.clone(),
                        callee: f.clone(),
                    })])
                } else {
                    Rc::new(vec![])
                }
            }
            _ => Rc::new(vec![]),
        };
        let child_edges = Rc::new({
            let mut __result = Vec::new();
            for child in texpr.children.clone().iter().cloned() {
                __result.extend(
                    (*collect_calls_in_expr(
                        caller.clone(),
                        child.clone(),
                        local_func_set.clone(),
                        source_indices.clone(),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let result = v1_rt::concat(this_edges.clone(), child_edges.clone());
        result
    })
}

